'<1>Leads</1> real form submissions'=>'<1>Leady</1> realne wysłania formularza',
'Table of contents'=>'Spis treści',
'In short'=>'W skrócie',
'What to count?'=>'Co liczyć?',
'Tracking models'=>'Modele pomiaru',
